        bytes memory callData1 = abi.encode(ActionData1, ActionData2, to, data);
        darcWETH.doActionWithLeverage(
            WETH.balanceOf(address(darcWETH)) - 1e18, address(Proxy1), address(ActionMultiCall), callData1, bytes3(0)
